(1, 'Medicine ID should Match in FTP, SAP, SharePoint,SQL ', 'SAP_Medicine', 'MedicineID', 'DMS_SAP_Medicine', 'MedicineID', NULL, TRUE, 'SQL_Medicine', 'MedicineID', 'DMS_SQL_Medicine', 'MedicineID', NULL, TRUE, 'SharePoint_Medicine', 'MedicineID', 'DMS_SharePoint_Medicine', 'MedicineID', NULL, TRUE, 'FTP_Medicine', 'MedicineID', 'DMS_FTP_Medicine', 'MedicineID', '1', 1, NULL, TRUE, NULL, FALSE, 'Present in All Sources', NULL, TRUE, '[MedicineConfig]', TRUE, TRUE, 'MedicineID', 'MedicineID', 'MedicineID', 'MedicineID', NULL, NULL, FALSE, 2, 19, 'MedicineConfig', 'MedicineID', 'Medicine ID should Match in FTP, SAP, SharePoint,SQL ', NULL, NULL, NULL, NULL, 'ShP+FTP+SAP+SQL', 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SELECT Distinct MedicineID From DMS_SAP_Medicine', 'SELECT Distinct MedicineID From DMS_SQL_Medicine', 'SELECT Distinct MedicineID From DMS_FTP_Medicine', 'UPDATE DMS_SAP_Medicine SET MedicineID = null Where MedicineID is null or MedicineID=''NULL''', 'UPDATE DMS_SQL_Medicine SET MedicineID = null Where MedicineID is null or MedicineID=''NULL''', 'UPDATE DMS_FTP_Medicine SET MedicineID = null Where MedicineID is null or MedicineID=''NULL''', 'SELECT Distinct MedicineID From DMS_SAP_Medicine UNION SELECT Distinct MedicineID From DMS_SQL_Medicine UNION SELECT Distinct MedicineID From DMS_FTP_Medicine', 'SELECT Distinct Cast(MedicineID As Varchar(200)) AS [BusinessPartner], Cast(MedicineID As Varchar(200)) AS ConfigValue INTO #TempConfigValueL2 From DMS_SAP_Medicine UNION SELECT Distinct Cast(MedicineID As Varchar(200)) AS [BusinessPartner], Cast(MedicineID As Varchar(200)) From DMS_SQL_Medicine UNION SELECT Distinct Cast(MedicineID As Varchar(200)) AS [BusinessPartner], Cast(MedicineID As Varchar(200)) From DMS_FTP_Medicine', 'INSERT INTO #DMS_FactL2Monitor
( [BusinessPartner],[ConfigValue], [IsSAP], [IsSQL],[IsFTP])
SELECT Distinct 
MAIN.[BusinessPartner]
,MAIN.ConfigValue
, CASE WHEN  SAP.ConfigValue IS NULL THEN 0 ELSE 1 END AS IsSAP
, CASE WHEN  SQL.ConfigValue  IS NULL THEN 0 ELSE 1 END AS IsSQL
, CASE WHEN  FTP.ConfigValue  IS NULL THEN 0 ELSE 1 END AS IsFTP
FROM #TempConfigValueL2 main
LEFT JOIN (SELECT Cast(MedicineID As Varchar(200)) AS [BusinessPartner], Cast(MedicineID As Varchar(200)) AS ConfigValue FROM DMS_SAP_Medicine ) SAP  
ON MAIN.ConfigValue = SAP.ConfigValue AND main.[BusinessPartner]=SAP.[BusinessPartner] 
LEFT JOIN (SELECT Cast(MedicineID As Varchar(200))  AS [BusinessPartner], Cast(MedicineID As Varchar(200)) AS ConfigValue From DMS_SQL_Medicine  ) SQL  
ON MAIN.ConfigValue = SQL.ConfigValue AND main.[BusinessPartner]=SQL.[BusinessPartner] 
LEFT JOIN (SELECT Cast(MedicineID As Varchar(200))  AS [BusinessPartner], Cast(MedicineID As Varchar(200)) AS ConfigValue From DMS_FTP_Medicine ) FTP  
ON MAIN.ConfigValue = FTP.ConfigValue AND main.[BusinessPartner]=FTP.[BusinessPartner] 
Where  MAIN.ConfigValue is not null and len(MAIN.ConfigValue)>0 and MAIN.[BusinessPartner] is not null');
